// -- the mark --------------------------------------------------------------
// Its own viewBox, and the numbers inside it, exactly as public/app.js has them.
const M = { x: 14, y: 8, w: 36, h: 50.5 };

// The three settled cards. 34 long, 6.95 thick, 1.15 of air between them.
const CARD = { x: 15, w: 34, h: 6.95, r: 1.6 };
const CARD_Y = [34.2, 42.3, 50.5];

// The one still coming down. It is NOT one of the three with a rotation on it:
// in the artwork it is measurably thicker and a little shorter, which is what
// makes it read as a card tipped toward you rather than a card lying flat.
const GOLD = { x: 15, y: 21.75, w: 33.2, h: 8.65, r: 1.8, tilt: -13, cx: 31.6, cy: 26.075 };

// Three motion ticks. Hairlines, not bars: 0.58 wide against the cards' 6.95.
const TICK_W = 0.58;
const TICK = [
  [27.3,  13.4, 6.15],
  [30.25,  9.0, 8.7],
  [33.2,  12.5, 5.75],
];

function MarkShapes({ c }) {
  return (
    <>
      <G stroke={c.markGold} strokeWidth={TICK_W} strokeLinecap="round">
        {TICK.map(([x, y, len], i) => (
          <Path key={i} d={`M${x} ${y}v${len}`} />
        ))}
      </G>
      <Rect
        x={GOLD.x} y={GOLD.y} width={GOLD.w} height={GOLD.h} rx={GOLD.r}
        fill={c.markGold}
        transform={`rotate(${GOLD.tilt} ${GOLD.cx} ${GOLD.cy})`}
      />
      {CARD_Y.map((y) => (
        <Rect key={y} x={CARD.x} y={y} width={CARD.w} height={CARD.h} rx={CARD.r}
          fill={c.markBlue} />
      ))}
    </>
  );
}

/* The mark on its own. `h` is the height of its viewBox, which is also the
   height the CSS gives it on the web, so 32 here and 32 there are the same
   drawing at the same size. Nothing should call this: see Lockup. */
export function Mark({ scheme, h = 32 }) {
  const c = palette(scheme);
  return (
    <Svg width={(M.w / M.h) * h} height={h} viewBox={`${M.x} ${M.y} ${M.w} ${M.h}`}>
      <MarkShapes c={c} />
    </Svg>
  );
}

/* The wordmark on its own. `size` is the type size it would be set at on the
   web. Nothing should call this either. */
export function Wordmark({ scheme, size = 34 }) {
  const c = palette(scheme);
  const k = size / W.em;
  const w = W.inkRight - W.inkLeft;
  return (
    <Svg
      width={w * k}
      height={(W.ascender + W.descender) * k}
      viewBox={`${W.inkLeft} ${-W.ascender} ${w} ${W.ascender + W.descender}`}
    >
      <G transform={`translate(${W.originX} 0)`}>
        <Path fill={c.ink} d={W.beat} />
        <Path fill={c.blue} d={W.fall} />
      </G>
    </Svg>
  );
}

/* THE LOCKUP. This is the brand; neither half is ever used alone.
 *
 * ONE number sets it: `size`, the type size of the name. The three ratios
 * below were measured off the master artwork and are the same three numbers
 * public/theme.css uses in its .brand and .mark rules.
 *
 *   MARK   the mark's viewBox height, as a multiple of the type size
 *   GAP    the air between the mark's box and the first stroke of the B
 *   DROP   how far the mark's box bottom sits BELOW the baseline. The artwork
 *          hangs the lowest card level with the foot of the a and the e,
 *          which overshoot the baseline slightly.
 */
const MARK = 0.9406;
const GAP  = 0.0974;
const DROP = 0.0315;

export function Lockup({ scheme, size = 34 }) {
  const c = palette(scheme);
  const u = W.em / size;              // px -> wordmark units
  const markH = size * MARK * u;
  const s = markH / M.h;              // mark units -> wordmark units
  const wordX = M.w * s + size * GAP * u;
  const dy = size * DROP * u;

  const top = Math.max(markH - dy, W.ascender);
  const bot = Math.max(W.descender, dy);
  const totalW = wordX + (W.inkRight - W.inkLeft);
  const k = size / W.em;

  return (
    <Svg
      width={totalW * k}
      height={(top + bot) * k}
      viewBox={`0 ${-top} ${totalW} ${top + bot}`}
      accessibilityRole="image"
      accessibilityLabel="Beatfall"
    >
      <G transform={`translate(0 ${dy}) scale(${s}) translate(${-M.x} ${-(M.y + M.h)})`}>
        <MarkShapes c={c} />
      </G>
      <G transform={`translate(${wordX - W.inkLeft + W.originX} 0)`}>
        <Path fill={c.ink} d={W.beat} />
        <Path fill={c.blue} d={W.fall} />
      </G>
    </Svg>
  );
}
